#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Provided by the candidate in solution.c */
int validate_command(const uint8_t *frame, size_t len, uint32_t *last_counter);

int main(void)
{
    char line[1024];
    uint32_t last_counter = 0;
    while (fgets(line, sizeof line, stdin) != NULL) {
        uint8_t frame[256];
        size_t len = 0;
        char *p = line;
        for (;;) {
            char *end;
            unsigned long v = strtoul(p, &end, 16);
            if (end == p || len >= sizeof frame) {
                break;
            }
            frame[len++] = (uint8_t)v;
            p = end;
        }
        printf("%d\n", validate_command(frame, len, &last_counter));
    }
    return 0;
}
